@layer components {
  :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-inline-size: calc(var(--spacing) * 9);
    --cui-switch-height: calc(var(--spacing) * 5);
    --cui-switch-padding: calc(var(--spacing) * 0.5);
    --cui-switch-thumb-inline-size: calc(var(--spacing) * 4);
    --cui-switch-thumb-press-inline-size: calc(var(--cui-switch-thumb-inline-size) * 1.25);
    --cui-switch-thumb-press-scale: 1;
    --cui-switch-thumb-backdrop-filter: none;
    --_switch-direction: 1;
    --_switch-progress: 0;
    --_switch-thumb-inline-size: var(--cui-switch-thumb-inline-size);
    --_switch-travel: calc(var(--cui-switch-inline-size) - var(--cui-switch-padding) * 2 - var(--_switch-thumb-inline-size));
    block-size: var(--cui-switch-height);
    inline-size: var(--cui-switch-inline-size);
    padding: var(--cui-switch-padding);
    touch-action: pan-y;
    user-select: none;
    --cui-switch-background: oklch(from var(--foreground) l c h / 0.14);
    --cui-switch-hover-background: oklch(from var(--foreground) l c h / 0.2);
    --cui-switch-press-background: color-mix(in oklch, var(--cui-switch-background), var(--foreground) 12.8%);
    --cui-switch-border-color: var(--control-boundary);
    --cui-switch-border-width: var(--control-rim-width);
    --cui-switch-checked-background: var(--primary);
    --cui-switch-checked-hover-background: color-mix(in oklch, var(--primary) 90%, var(--foreground));
    --cui-switch-checked-press-background: color-mix(in oklch, var(--cui-switch-checked-background) 80%, var(--foreground));
    --cui-switch-checked-border-color: transparent;
    --cui-switch-radius: 9999px;
    --cui-switch-shadow: 0 0 transparent;
    --cui-switch-thumb-radius: 9999px;
    --cui-switch-thumb-background: var(--background);
    --cui-switch-thumb-shadow: var(--shadow-sm);
    --_switch-border-color: var(--cui-switch-border-color);
    --_switch-ring: 0 0 transparent;
    border-radius: var(--cui-switch-radius);
    background: var(--cui-switch-background);
    box-shadow:
      inset 0 0 0 var(--cui-switch-border-width) var(--_switch-border-color),
      var(--cui-switch-shadow),
      var(--_switch-ring);
    cursor: pointer;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]) {
    --_switch-progress: 1;
    --_switch-border-color: var(--cui-switch-checked-border-color);
    background: var(--cui-switch-checked-background);
  }

  @media (hover: hover) {
    :where([data-control-family="switch"][data-slot="root"]:hover:not([data-checked], [data-disabled], [data-readonly])) {
      background: var(--cui-switch-hover-background);
    }

    :where([data-control-family="switch"][data-slot="root"][data-checked]:hover:not([data-disabled], [data-readonly])) {
      background: var(--cui-switch-checked-hover-background);
    }
  }

  :where([data-control-family="switch"][data-slot="root"]:active:not([data-checked], [data-disabled], [data-readonly])) {
    background: var(--cui-switch-press-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked]:active:not([data-disabled], [data-readonly])) {
    background: var(--cui-switch-checked-press-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-disabled]) {
    opacity: var(--disabled-opacity);
    cursor: not-allowed;
  }

  :where([data-control-family="switch"][data-slot="root"]:is([data-invalid], [aria-invalid="true"])) {
    --_switch-border-color: var(--destructive);
    --_switch-ring: 0 0 0 1px var(--destructive);
  }

  @media (pointer: coarse) {
    :where([data-control-family="switch"][data-slot="root"])::after {
      content: "";
      position: absolute;
      inset: 50% auto auto 50%;
      translate: -50% -50%;
      inline-size: max(100%, var(--touch-target));
      block-size: max(100%, var(--touch-target));
    }
  }

  :where([data-control-family="switch"][data-slot="thumb"]) {
    border-radius: var(--cui-switch-thumb-radius);
    background: var(--cui-switch-thumb-background);
    box-shadow: var(--cui-switch-thumb-shadow);
    inline-size: var(--_switch-thumb-inline-size);
    block-size: calc(var(--cui-switch-height) - var(--cui-switch-padding) * 2);
    translate: calc(var(--_switch-direction) * var(--_switch-travel) * var(--_switch-progress)) 0;
    transform-origin: left center;
    -webkit-backdrop-filter: var(--cui-switch-thumb-backdrop-filter);
    backdrop-filter: var(--cui-switch-thumb-backdrop-filter);
    transition-property: translate, inline-size, scale, background-color, box-shadow;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"]) {
    color: oklch(from var(--foreground) l c h / 0.7);
    transition-property: color, opacity;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"] svg) {
    inline-size: calc(var(--spacing) * 2.5);
    block-size: calc(var(--spacing) * 2.5);
    stroke-width: 2.5;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-slot="thumb-icon"]:not([data-switch-icon="unchecked"])) {
    color: var(--primary-text);
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"][data-switch-icon="unchecked"]) {
    color: oklch(from var(--foreground) l c h / 0.6);
    opacity: 1;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-switch-icon="unchecked"]) {
    opacity: 0;
  }

  :where([data-control-family="switch"][data-slot="thumb-icon"][data-switch-icon="checked"]) {
    color: var(--primary-text);
    opacity: 0;
  }

  :where([data-control-family="switch"][data-slot="root"][data-checked] [data-switch-icon="checked"]) {
    opacity: 1;
  }

  :where([data-control-family="switch"][data-slot="root"]:dir(rtl)) {
    --_switch-direction: -1;
  }

  :where([data-control-family="switch"][data-slot="thumb"][data-checked]),
  :where([data-control-family="switch"][data-slot="thumb"]:dir(rtl)) {
    transform-origin: right center;
  }

  :where([data-control-family="switch"][data-slot="thumb"][data-checked]:dir(rtl)) {
    transform-origin: left center;
  }

  :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging]):not([data-disabled], [data-readonly])) {
    --_switch-thumb-inline-size: var(--cui-switch-thumb-press-inline-size);
  }

  :where(
    [data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging]):not([data-disabled], [data-readonly]) [data-slot="thumb"]
  ) {
    scale: var(--cui-switch-thumb-press-scale);
  }

  :where([data-control-family="switch"][data-slot="root"][data-dragging]) {
    --_switch-progress: var(--_switch-drag-progress);
  }

  :where([data-control-family="switch"][data-slot="root"][data-drag-checked="false"]) {
    --_switch-border-color: var(--cui-switch-border-color);
    background: var(--cui-switch-press-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-drag-checked="true"]) {
    --_switch-border-color: var(--cui-switch-checked-border-color);
    background: var(--cui-switch-checked-press-background);
  }

  :where([data-control-family="switch"][data-slot="root"][data-dragging] [data-slot="thumb"]) {
    transition-property: inline-size, scale, background-color, box-shadow;
  }

  @media (forced-colors: active) {
    :where([data-control-family="switch"][data-slot="root"]:not(:focus-visible)) {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }

    :where([data-control-family="switch"][data-slot="root"][data-checked]) {
      background: Highlight;
    }

    :where([data-control-family="switch"][data-slot="thumb"]) {
      background: CanvasText;
    }

    :where([data-control-family="switch"][data-slot="root"][data-checked] [data-slot="thumb"]) {
      background: HighlightText;
    }

    :where([data-control-family="switch"][data-slot="thumb-icon"]) {
      color: Canvas;
    }

    :where([data-control-family="switch"][data-slot="root"][data-checked] [data-slot="thumb-icon"]) {
      color: Highlight;
    }
  }
}

